+async function findNearMissPackagesInDir(dir: string): Promise<NearMissPackage[]> {
+	try {
+		const entries = await readdir(dir, { withFileTypes: true });
+		const nearMisses: NearMissPackage[] = [];
+
+		for (const entry of entries) {
